sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float2 center;
uniform float radius;
half4 main(float2 coord){float2 c=center*size;float2 v=coord-c;float r=length(v)/max(radius*min(size.x,size.y),1.0);float f=1.0+amount*(1.0-smoothstep(0.0,1.0,r));return image.eval(c+v*f);}
